 "content": "def transform(grid):
    # Find the large solid rectangle color, ignoring sparse background speckles.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    rectangles = []
    for color in counts:
        if color == bg:
            continue
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(pts) < 4:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        area = (r1-r0+1)*(c1-c0+1)
        if len(pts)/area >= 0.55:
            rectangles.append((len(pts), color, r0, r1, c0, c1))
    if not rectangles:
        return [row[:] for row in grid]
    _, color, r0, r1, c0, c1 = max(rectangles)
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(r0, r1+1):
